function addFrame(p,x,y,w,h,fill,r,name){const f=figma.createFrame();p.appendChild(f);f.resize(w,h);f.fills=fill?[{type:"SOLID",color:fill}]:[];if(r!==undefined)f.cornerRadius=r;f.x=x;f.y=y;if(name)f.name=name;f.clipsContent=false;return f;}
function addText(p,font,size,color,chars,x,y,w,opts={}){const t=figma.createText();p.appendChild(t);t.fontName={family:font[0],style:font[1]};t.fontSize=size;t.characters=chars;t.fills=[{type:"SOLID",color}];if(opts.lh)t.lineHeight={unit:"PERCENT",value:opts.lh};if(opts.ls!==undefined)t.letterSpacing={unit:"PERCENT",value:opts.ls};if(opts.align)t.textAlignHorizontal=opts.align;if(w){t.resize(w,10);t.textAutoResize="HEIGHT";}t.x=x;t.y=y;if(opts.name)t.name=opts.name;return t;}
function addRect(p,x,y,w,h,fill,op){const r=figma.createRectangle();p.appendChild(r);r.resize(w,h);r.fills=[{type:"SOLID",color:fill,opacity:op??1}];r.x=x;r.y=y;return r;}
function addDot(p,x,y,d,fill,op){const e=figma.createEllipse();p.appendChild(e);e.resize(d,d);e.fills=[{type:"SOLID",color:fill,opacity:op??1}];e.x=x;e.y=y;return e;}
let seed=11;const rnd=()=>{seed=(seed*16807)%2147483647;return seed/2147483647;};
function starfield(p,x,y,w,h,n,name){const f=addFrame(p,x,y,w,h,null,undefined,name||"Starfield");for(let i=0;i<n;i++){const r=rnd();const col=r<.7?C.green:r<.9?C.amber:C.red;const d=3+Math.round(rnd()*rnd()*14);addDot(f,Math.round(rnd()*(w-d)),Math.round(rnd()*(h-d)),d,col,.2+rnd()*.5);}return f;}
